// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address _baseToken, uint128 _vBase) public {
        address _nft = address(this);
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        uint16 _feeRate = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        bool ok;
        try c.initialize(_baseToken, _nft, _vBase, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.baseToken() == _baseToken);
        } else {
            assertTrue(c.baseToken() == address(0));
        }
    }
}
